using System;
using System.Linq;
using LastRail.Presentation.MissionShell;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {public sealed class ObjectiveProgressValidationTests {
 static JObject Data(string time){var now=DateTimeOffset.Parse(time);var service=now.AddHours(5);var day=new DateTimeOffset(service.Year,service.Month,service.Day,0,0,0,TimeSpan.Zero).AddHours(-5);var month=new DateTimeOffset(service.Year,service.Month,1,0,0,0,TimeSpan.Zero).AddHours(-5);int index=(int)(day-month).TotalDays;var systems=new JArray();foreach(var system in new[]{"QUESTS","PASS50"}){var rows=new JArray();foreach(var id in new[]{"D1","D2","D3","W1","W2","W3"}){if(system=="QUESTS"&&id=="D1")continue;bool weekly=id.StartsWith("W"),login=id=="D1"||id=="W1",scheduled=!(system=="PASS50"&&weekly&&index>=28);var start=weekly?system=="QUESTS"?day.AddDays(-(((int)service.DayOfWeek+6)%7)):month.AddDays(index/7*7):day;var period=weekly?system=="QUESTS"?"W:"+start.ToUnixTimeMilliseconds():"W:"+month.ToUnixTimeMilliseconds()+":"+index/7:"D:"+start.ToUnixTimeMilliseconds();rows.Add(new JObject{["objectiveId"]=id,["frequency"]=weekly?"WEEKLY":"DAILY",["metric"]=login?"login":id=="W3"?"waves":"ends",["target"]=id=="W3"?60:id=="W2"?6:id=="W1"?3:id=="D3"?2:1,["periodId"]=scheduled?new JValue(period):JValue.CreateNull(),["periodStartAt"]=scheduled?new JValue(start.ToUnixTimeMilliseconds()):JValue.CreateNull(),["periodEndAt"]=scheduled?new JValue(start.AddDays(weekly?7:1).ToUnixTimeMilliseconds()):JValue.CreateNull(),["calendar"]=weekly?system=="QUESTS"?"MONDAY_04_KST":"SEASON_RELATIVE_7_DAYS":"DAILY_04_KST",["current"]=scheduled&&login?new JValue(0):JValue.CreateNull(),["observedCurrent"]=scheduled?new JValue(0):JValue.CreateNull(),["currentScope"]=login?"SERVER_RECORDED_LOGIN":"RECORDED_ELIGIBLE_OWNER_FINISH",["coverage"]=!scheduled?"NOT_SCHEDULED":login?"COMPLETE_FOR_RECORDED_LOGIN":"PARTIAL_UNKNOWN",["unknownReasons"]=scheduled&&!login?new JArray("COOPERATIVE_PARTICIPANT_PRODUCER_MISSING"):new JArray(),["observedTargetReached"]=false,["syncPending"]=false,["awardId"]=null,["status"]=!scheduled?"NOT_SCHEDULED":login?"IN_PROGRESS":"UNKNOWN",["xp"]=system=="QUESTS"?0:40,["rewards"]=new JArray()});}systems.Add(new JObject{["system"]=system,["policyId"]="fixture-"+system,["status"]="ACTIVE",["objectives"]=rows});}return new JObject{["version"]="objective-progress-v1",["serverTime"]=now.ToUnixTimeMilliseconds(),["appliedEventId"]=0,["latestEventId"]=0,["systems"]=systems};}
 [Test] public void MissingCoverageCannotBecomeCompleteZero(){var d=Data("2026-09-10T00:00:00Z");Assert.DoesNotThrow(()=>new ObjectiveProgress(d));var row=(JObject)d["systems"][0]["objectives"][0];row["current"]=0;Assert.Throws<FormatException>(()=>new ObjectiveProgress(d));}
 [Test] public void Day29WeeklyRowsRemainUnscheduledNull(){var state=new ObjectiveProgress(Data("2026-09-28T19:00:00Z"));foreach(JObject row in state.SystemState("PASS50")["objectives"].Where(r=>(string)r["frequency"]=="WEEKLY")){Assert.That(row["current"].Type,Is.EqualTo(JTokenType.Null));Assert.That(ObjectiveProgress.ProgressText(row),Is.EqualTo("이번 기간 미운영"));}var d=Data("2026-09-28T19:00:00Z");d["systems"][1]["objectives"][3]["observedCurrent"]=0;Assert.Throws<FormatException>(()=>new ObjectiveProgress(d));}
 [Test] public void ThresholdWithoutAwardRequiresSyncNotClaim(){var d=Data("2026-09-10T00:00:00Z");var row=(JObject)d["systems"][0]["objectives"][0];row["observedCurrent"]=1;row["observedTargetReached"]=true;row["syncPending"]=true;row["status"]="SYNC_PENDING";Assert.DoesNotThrow(()=>new ObjectiveProgress(d));row["status"]="EARNED";Assert.Throws<FormatException>(()=>new ObjectiveProgress(d));}
 [Test] public void NestedSnapshotOwnsClockAndClone(){var d=Data("2026-10-01T00:00:00Z");var state=new ObjectiveProgress(d);d["systems"][0]["objectives"][0]["current"]=500;Assert.That(state.SystemState("QUESTS")["objectives"][0]["current"].Type,Is.EqualTo(JTokenType.Null));var system=state.SystemState("QUESTS");system["policyId"]="changed";Assert.That((string)state.SystemState("QUESTS")["policyId"],Is.Not.EqualTo("changed"));}
} }

